#[macro_export]
macro_rules! peek_atomic_update {
    ($($tail:tt)*) => {
        {
            #[verifier::exec]
            let err_au = ::verus_builtin_macros::verus_exec_open_au_macro_exprs!(
                $crate::atomic::try_open_atomic_update_internal!(
                    $($tail)*, @EXEC, au_abort_wrap_exec
                )
